import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    N_max = 199
    count_coprime_to_6 = 0
    count_failing = 0

    for n in range(2, N_max + 1):
        if gcd(n, 6) != 1:
            continue

        is_failing = False

        # Check the condition derived from k=p being a prime factor of n-2a
        # n must not be congruent to p (mod 2p) for any odd prime p such that p <= n-1.

        primes = []
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False
        for p in range(2, n + 1):
            if is_prime[p]:
                primes.append(p)
                for i in range(p * p, n + 1, p):
                    is_prime[i] = False

        for p in primes:
            if p == 2 or p == 3:
                continue

            if p > n - 1:
                # Optimization: no need to check primes larger than n-1
                break

            # Check the failure condition: n == p (mod 2p)
            if n % (2 * p) == p:
                # Found a prime p such that n = p (mod 2p). This implies a=(n-p)/2 is divisible by p,
                # causing p to not divide binomial(a-1, p-1).
                is_failing = True
                break

        if is_failing:
            count_failing += 1
        else:
            count_coprime_to_6 += 1

    return count_coprime_to_6

print(solve())
